bites_fmt() {
  local key="$1" packed="" pair
  shift
  bites_text "$key" || { printf 'bites: no message %s in the catalog\n' "$key" >&2; return 1; }
  # The values travel to awk through the environment, joined by an SOH character, so that no
  # character in a value (a backslash, an ampersand, a brace, a newline) is ever interpreted.
  for pair in "$@"; do packed="$packed$pair"$'\001'; done
  BITES_T="$BITES_TEXT" BITES_V="$packed" awk '
    BEGIN {
      t = ENVIRON["BITES_T"]
      v = ENVIRON["BITES_V"]
      while ((q = index(v, "\001")) > 0) {
        pair = substr(v, 1, q - 1)
        v = substr(v, q + 1)
        p = index(pair, "=")
        if (p > 0) name[substr(pair, 1, p - 1)] = substr(pair, p + 1)
      }
      out = ""
      while (length(t) > 0) {
        c = substr(t, 1, 1)
        if (c == "{") {
          if (substr(t, 2, 1) == "{") { out = out "{"; t = substr(t, 3); continue }
          e = index(t, "}")
          nm = substr(t, 2, e - 2)
          if (e == 0 || !(nm in name)) { printf "bites: no value for {%s}\n", nm > "/dev/stderr"; exit 2 }
          out = out name[nm]
          t = substr(t, e + 1)
        } else if (c == "}") {
          out = out "}"
          t = substr(t, (substr(t, 2, 1) == "}") ? 3 : 2)
        } else {
          m = match(t, /[{}]/)
          if (m == 0) { out = out t; t = "" } else { out = out substr(t, 1, m - 1); t = substr(t, m) }
        }
      }
      printf "%s", out
    }'
}

# Runner commands use stderr so command substitutions and formatted stdout stay intact.
# The runner accepts commands on either stream. Keep human diagnostics separate.
bites_annotate() {
  local level="$1" title="$2" body="$3"
  case "$level" in error|warning) ;; *) return 2 ;; esac
  [ "${GITHUB_ACTIONS:-}" = true ] || return 0
  title=${title//%/%25}; title=${title//$'\r'/%0D}; title=${title//$'\n'/%0A}
  title=${title//:/%3A}; title=${title//,/%2C}
  body=${body//%/%25}; body=${body//$'\r'/%0D}; body=${body//$'\n'/%0A}
  printf '::%s title=%s::%s\n' "$level" "$title" "$body" >&2
}
